<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue'
import {user,request} from '../services/auth'
import {orderError} from '../services/orders'
import {pendingAction,startAction,retryAction,type Coordination,type OrderException,type Action} from '../services/orderLifecycle'
const id=location.pathname.split('/')[3],selected=ref<Coordination|null>(null),listing=ref<{items:OrderException[];page:number;size:number;total:number}>({items:[],page:1,size:20,total:0}),busy=ref(false),error=ref(''),notice=ref(''),reason=ref(''),pending=ref<Action|null>(id?pendingAction(id,'control'):null)
let sequence=0
const labels={PAUSE:'暂停恢复',RESUME:'恢复原任务',CHECK:'立即核对'}
async function load(page=listing.value.page){const owner=user.value?.userId;if(!owner||busy.value)return;const seq=sequence;busy.value=true;error.value='';try{if(id){const c=await request<Coordination>('/admin/orders/'+encodeURIComponent(id)+'/coordination',owner);if(seq===sequence)selected.value=c}else{const list=await request<typeof listing.value>('/admin/orders/exceptions?page='+page+'&size=20',owner);if(seq===sequence)listing.value=list}}catch(e){if(seq===sequence)error.value=orderError(e)}finally{if(seq===sequence)busy.value=false}}
async function control(action?:'PAUSE'|'RESUME'|'CHECK'){if(!id||!selected.value||busy.value)return;const seq=sequence;busy.value=true;error.value='';notice.value='';try{const r=action?await startAction<{operationId:string;coordination:Coordination}>(id,'control',reason.value,action,selected.value.version):await retryAction<{operationId:string;coordination:Coordination}>(pending.value!);if(seq===sequence){notice.value='原任务控制已受理，请刷新查看当前进度。';selected.value=r.coordination;pending.value=null}}catch(e){if(seq===sequence)error.value=orderError(e)}finally{if(seq===sequence){pending.value=pendingAction(id,'control');busy.value=false}}}
watch(()=>user.value?.userId,()=>{sequence++;selected.value=null;listing.value={items:[],page:1,size:20,total:0};pending.value=id?pendingAction(id,'control'):null;busy.value=false;notice.value='';reason.value='';void load()})
onMounted(()=>void load());onUnmounted(()=>sequence++)
</script>
<template><section><h1>订单异常管理</h1><button :disabled="busy" @click="load()">刷新核对</button><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><template v-if="selected"><h2>订单 {{selected.orderId}}</h2><p>任务 {{selected.intent}} · {{selected.runState}} · 版本 {{selected.version}}</p><p>{{selected.paused?'已暂停':'未暂停'}} · 连续失败 {{selected.consecutiveFailures}} 次 · {{selected.alerted?'已告警':'未告警'}}</p><p v-if="selected.errorCode">提示 {{selected.errorCode}}</p><p>立即核对只检查原订单；鉴权故障须核验通过才恢复，证据矛盾不能通过页面强制恢复。</p><template v-if="pending"><p>控制结果待核对 · {{pending.body.operationId}}</p><button :disabled="busy" @click="control()">重试原控制</button></template><template v-else><label>操作原因<input v-model="reason" maxlength="256" :disabled="busy"></label><button v-for="action in selected.allowedActions" :key="action" :disabled="busy||!reason.trim()" @click="control(action)">{{labels[action]}}</button><p v-if="!selected.allowedActions.length">当前无可执行动作。</p></template><h3>最近尝试</h3><p v-for="attempt in selected.recentAttempts" :key="attempt.requestId">{{attempt.intent}} · {{attempt.code}} · {{new Date(attempt.startedAt).toLocaleString()}} · {{attempt.message}}</p><a href="/admin/orders">返回异常列表</a></template><template v-else><p v-if="!listing.items.length&&!busy">暂无异常订单。</p><article v-for="o in listing.items" :key="o.orderId"><p>{{o.orderId}} · {{o.status}} · {{o.reviewRequired?'需要核对':'处理中'}}</p><a :href="'/admin/orders/'+o.orderId">查看协调记录</a></article><button :disabled="busy||listing.page<=1" @click="load(listing.page-1)">上一页</button><span>第 {{listing.page}} 页</span><button :disabled="busy||listing.page*listing.size>=listing.total" @click="load(listing.page+1)">下一页</button></template></section></template>
